-- =============================================================================
-- Migration 0062: Examentraining — bereken p bij een oppervlakte
-- =============================================================================
-- Gegenereerd door scripts/examen-oppervlakte-parameter.ts — niet met de hand bewerken.
--
-- Eigen onderdeel Examentraining, geen theoriehoofdstuk uit het boek.
-- De oppervlakte hangt van p af. Die is gelijk aan een gegeven getal,
-- of gelijk aan de oppervlakte van een ander genoemd vlakdeel.
-- Het antwoord is de waarde van p. Acht vragen, allemaal niveau 3.
--
-- Eigen oefenvragen, geen boek- of examenopgaven. Elke integraal wordt
-- nagerekend door src/content/primitieven.test.ts
-- (content/hoofdstuk-examen/oppervlakte-parameter.json).
--
-- Alleen toevoegen: geen DELETE, DROP, ALTER of UPDATE. Twee keer draaien
-- voegt niets dubbel toe.
--
--   • 1 hoofdstuk, 1 topics, 1 clusters
--   • 8 vragen met elk 4 stappen (32 stappen)
-- =============================================================================

BEGIN;

-- 1. Hoofdstuk
INSERT INTO public.chapters (slug, title, book_part, order_index, site)
VALUES ('examentraining', $examentrainingsql$Examentraining$examentrainingsql$, 5, 16, 'integralen')
ON CONFLICT (slug) DO NOTHING;

-- 2. Topics
INSERT INTO public.topics_new (slug, title, chapter_id, order_index, is_unlocked_by_default, site, category)
SELECT v.slug, v.title, (SELECT id FROM public.chapters WHERE slug = 'examentraining' AND site = 'integralen'), v.order_index, true, 'integralen', v.category
FROM (VALUES
  ('examen_opp_parameter', $examentrainingsql$Oppervlakte en de waarde van p$examentrainingsql$, 4, 'toepassingen')
) AS v(slug, title, order_index, category)
ON CONFLICT (slug) DO NOTHING;

-- 3. Clusters
INSERT INTO public.topic_clusters_new (topic_id, slug, title, order_index, site)
SELECT t.id, v.slug, v.title, v.order_index, 'integralen'
FROM (VALUES
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Bereken p$examentrainingsql$, 1)
) AS v(topic_slug, slug, title, order_index)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
ON CONFLICT (topic_id, slug) DO NOTHING;

-- 4. Vragen
INSERT INTO public.questions_new
  (site, topic_id, cluster_id, latex_body, answer, latex_answer, difficulty, order_index, is_ai_generated, answer_alternatives)
SELECT 'integralen', t.id, cl.id, v.latex_body, v.answer, v.latex_answer, v.difficulty, v.order_index, false, v.alternatives
FROM (VALUES
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Voor elke $p$ met $0 < p < 4$ sluit de grafiek van $f(x) = 4x - x^{2}$ met de $x$-as en de lijn $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $\dfrac{16}{3}$.$examentrainingsql$, $examentrainingsql$2$examentrainingsql$, $examentrainingsql$p = 2$examentrainingsql$, 3, 1, ARRAY[$examentrainingsql$p = 2$examentrainingsql$, $examentrainingsql$p=2$examentrainingsql$]::text[]),
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Voor elke $p > 0$ sluit de grafiek van $f(x) = \dfrac{px + 3}{x + 1}$ met de $x$-as en de lijnen $x = 0$ en $x = 1$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $2 + \ln(2)$.$examentrainingsql$, $examentrainingsql$2$examentrainingsql$, $examentrainingsql$p = 2$examentrainingsql$, 3, 2, ARRAY[$examentrainingsql$p = 2$examentrainingsql$, $examentrainingsql$p=2$examentrainingsql$]::text[]),
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Voor elke $p > 0$ sluit de grafiek van $f(x) = \sqrt{4x + 4}$ met de $x$-as en de lijnen $x = 0$ en $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $\dfrac{28}{3}$.$examentrainingsql$, $examentrainingsql$3$examentrainingsql$, $examentrainingsql$p = 3$examentrainingsql$, 3, 3, ARRAY[$examentrainingsql$p = 3$examentrainingsql$, $examentrainingsql$p=3$examentrainingsql$]::text[]),
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Voor elke $p > 0$ sluit de grafiek van $f(x) = e^{x}$ met de $x$-as, de $y$-as en de lijn $x = p$ een vlakdeel $V_p$ in. Het vlakdeel $W$ wordt ingesloten door de grafiek van $g(x) = 3e^{3x}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan de oppervlakte van $W$.$examentrainingsql$, $examentrainingsql$3$examentrainingsql$, $examentrainingsql$p = 3$examentrainingsql$, 3, 4, ARRAY[$examentrainingsql$p = 3$examentrainingsql$, $examentrainingsql$p=3$examentrainingsql$]::text[]),
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Voor elke $p > 1$ sluit de grafiek van $f(x) = \ln(x)$ met de $x$-as en de lijnen $x = 1$ en $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $1$.$examentrainingsql$, $examentrainingsql$e$examentrainingsql$, $examentrainingsql$p = e$examentrainingsql$, 3, 5, ARRAY[$examentrainingsql$p = e$examentrainingsql$, $examentrainingsql$p=e$examentrainingsql$]::text[]),
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Voor elke $p$ met $0 < p \le \dfrac{\pi}{2}$ sluit de grafiek van $f(x) = \sin(2x)$ met de $x$-as en de lijnen $x = 0$ en $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $1$.$examentrainingsql$, $examentrainingsql$pi/2$examentrainingsql$, $examentrainingsql$p = \dfrac{\pi}{2}$examentrainingsql$, 3, 6, ARRAY[$examentrainingsql$p = pi/2$examentrainingsql$, $examentrainingsql$p=pi/2$examentrainingsql$, $examentrainingsql$(1/2)*pi$examentrainingsql$, $examentrainingsql$pi/2$examentrainingsql$]::text[]),
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Voor elke $p$ met $0 < p \le \dfrac{\pi}{6}$ sluit de grafiek van $f(x) = \cos(3x)$ met de $x$-as en de lijnen $x = 0$ en $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $\dfrac{1}{3}$.$examentrainingsql$, $examentrainingsql$pi/6$examentrainingsql$, $examentrainingsql$p = \dfrac{\pi}{6}$examentrainingsql$, 3, 7, ARRAY[$examentrainingsql$p = pi/6$examentrainingsql$, $examentrainingsql$p=pi/6$examentrainingsql$, $examentrainingsql$(1/6)*pi$examentrainingsql$, $examentrainingsql$pi/6$examentrainingsql$]::text[]),
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Het vlakdeel $W$ wordt ingesloten door de grafiek van $f(x) = 4 - x$, de $x$-as en de lijnen $x = 0$ en $x = 4$. Voor elke $p$ met $0 < p < 4$ snijdt de lijn $x = p$ het vlakdeel $W$ in een linkerdeel $V$ en een rechterdeel. Bereken exact de waarde van $p$ waarvoor die twee delen dezelfde oppervlakte hebben.$examentrainingsql$, $examentrainingsql$4 - 2*sqrt(2)$examentrainingsql$, $examentrainingsql$p = 4 - 2\sqrt{2}$examentrainingsql$, 3, 8, ARRAY[$examentrainingsql$4-2sqrt(2)$examentrainingsql$, $examentrainingsql$4 - sqrt(8)$examentrainingsql$, $examentrainingsql$p = 4 - 2*sqrt(2)$examentrainingsql$, $examentrainingsql$p=4-2*sqrt(2)$examentrainingsql$]::text[])
) AS v(topic_slug, cluster_slug, latex_body, answer, latex_answer, difficulty, order_index, alternatives)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
JOIN public.topic_clusters_new cl ON cl.slug = v.cluster_slug AND cl.topic_id = t.id
WHERE NOT EXISTS (
  SELECT 1 FROM public.questions_new bestaand
  WHERE bestaand.cluster_id = cl.id AND bestaand.latex_body = v.latex_body
);

-- 5. Stappen (step_order 0 t/m 3)
INSERT INTO public.question_steps_new (question_id, step_order, step_description)
SELECT vr.id, v.step_order, v.step_description
FROM (VALUES
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Voor elke $p$ met $0 < p < 4$ sluit de grafiek van $f(x) = 4x - x^{2}$ met de $x$-as en de lijn $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $\dfrac{16}{3}$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen alle drie de delen: eerst vertaal je het verhaal naar een integraal, daarna reken je die uit (er komt een uitdrukking in $p$ uit), en tot slot los je de vergelijking op. Op $[0, p]$ ligt de grafiek boven de $x$-as, want $f(x) = x(4 - x)$ en $0 < p < 4$. De oppervlakte is dus de integraal zelf.$examentrainingsql$),
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Voor elke $p$ met $0 < p < 4$ sluit de grafiek van $f(x) = 4x - x^{2}$ met de $x$-as en de lijn $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $\dfrac{16}{3}$.$examentrainingsql$, 1, $examentrainingsql$$O(V_p) = \displaystyle\int_{0}^{p} (4x - x^{2})\,\mathrm{d}x$.$examentrainingsql$),
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Voor elke $p$ met $0 < p < 4$ sluit de grafiek van $f(x) = 4x - x^{2}$ met de $x$-as en de lijn $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $\dfrac{16}{3}$.$examentrainingsql$, 2, $examentrainingsql$Een primitieve is $F(x) = 2x^{2} - \dfrac{1}{3}x^{3}$. Dus $O(V_p) = 2p^{2} - \dfrac{1}{3}p^{3}$.$examentrainingsql$),
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Voor elke $p$ met $0 < p < 4$ sluit de grafiek van $f(x) = 4x - x^{2}$ met de $x$-as en de lijn $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $\dfrac{16}{3}$.$examentrainingsql$, 3, $examentrainingsql$Deel 3: $2p^{2} - \dfrac{1}{3}p^{3} = \dfrac{16}{3}$. Vermenigvuldig met $3$: $6p^{2} - p^{3} = 16$, dus $p^{3} - 6p^{2} + 16 = 0$. Je probeert $p = 2$: $8 - 24 + 16 = 0$. Delen door $p - 2$ geeft $(p - 2)(p^{2} - 4p - 8) = 0$. Uit $p^{2} - 4p - 8 = 0$ volgt $p = 2 \pm 2\sqrt{3}$. Alleen $p = 2$ ligt tussen $0$ en $4$.$examentrainingsql$),
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Voor elke $p > 0$ sluit de grafiek van $f(x) = \dfrac{px + 3}{x + 1}$ met de $x$-as en de lijnen $x = 0$ en $x = 1$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $2 + \ln(2)$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen alle drie de delen: eerst vertaal je het verhaal naar een integraal, daarna reken je die uit (er komt een uitdrukking in $p$ uit), en tot slot los je de vergelijking op. Op $[0, 1]$ zijn teller en noemer positief zolang $p > 0$, dus de grafiek ligt boven de $x$-as. Schrijf de breuk eerst als een getal plus een rest.$examentrainingsql$),
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Voor elke $p > 0$ sluit de grafiek van $f(x) = \dfrac{px + 3}{x + 1}$ met de $x$-as en de lijnen $x = 0$ en $x = 1$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $2 + \ln(2)$.$examentrainingsql$, 1, $examentrainingsql$$px + 3 = p(x + 1) + (3 - p)$, dus $f(x) = p + \dfrac{3 - p}{x + 1}$. $O(V_p) = \displaystyle\int_{0}^{1} \left(p + \dfrac{3 - p}{x + 1}\right)\,\mathrm{d}x$.$examentrainingsql$),
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Voor elke $p > 0$ sluit de grafiek van $f(x) = \dfrac{px + 3}{x + 1}$ met de $x$-as en de lijnen $x = 0$ en $x = 1$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $2 + \ln(2)$.$examentrainingsql$, 2, $examentrainingsql$Een primitieve is $F(x) = px + (3 - p)\ln(x + 1)$. Op $[0, 1]$ is $x + 1$ positief. $O(V_p) = F(1) - F(0) = p + (3 - p)\ln(2)$.$examentrainingsql$),
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Voor elke $p > 0$ sluit de grafiek van $f(x) = \dfrac{px + 3}{x + 1}$ met de $x$-as en de lijnen $x = 0$ en $x = 1$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $2 + \ln(2)$.$examentrainingsql$, 3, $examentrainingsql$Deel 3: $p + (3 - p)\ln(2) = 2 + \ln(2)$. Haal de termen met $p$ bij elkaar: $p(1 - \ln(2)) = 2(1 - \ln(2))$. Deel door $1 - \ln(2)$. Je vindt $p = 2$.$examentrainingsql$),
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Voor elke $p > 0$ sluit de grafiek van $f(x) = \sqrt{4x + 4}$ met de $x$-as en de lijnen $x = 0$ en $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $\dfrac{28}{3}$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen alle drie de delen: eerst vertaal je het verhaal naar een integraal, daarna reken je die uit (er komt een uitdrukking in $p$ uit), en tot slot los je de vergelijking op. Op $[0, p]$ is $4x + 4 > 0$, dus de grafiek ligt boven de $x$-as.$examentrainingsql$),
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Voor elke $p > 0$ sluit de grafiek van $f(x) = \sqrt{4x + 4}$ met de $x$-as en de lijnen $x = 0$ en $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $\dfrac{28}{3}$.$examentrainingsql$, 1, $examentrainingsql$$O(V_p) = \displaystyle\int_{0}^{p} \sqrt{4x + 4}\,\mathrm{d}x$. De kern is $4x + 4$, en die heeft afgeleide $4$.$examentrainingsql$),
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Voor elke $p > 0$ sluit de grafiek van $f(x) = \sqrt{4x + 4}$ met de $x$-as en de lijnen $x = 0$ en $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $\dfrac{28}{3}$.$examentrainingsql$, 2, $examentrainingsql$Een primitieve is $F(x) = \dfrac{1}{6}(4x + 4)^{3/2}$. Dus $O(V_p) = \dfrac{1}{6}\left((4p + 4)^{3/2} - 8\right)$.$examentrainingsql$),
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Voor elke $p > 0$ sluit de grafiek van $f(x) = \sqrt{4x + 4}$ met de $x$-as en de lijnen $x = 0$ en $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $\dfrac{28}{3}$.$examentrainingsql$, 3, $examentrainingsql$Deel 3: $\dfrac{1}{6}\left((4p + 4)^{3/2} - 8\right) = \dfrac{28}{3}$. Dan $(4p + 4)^{3/2} = 64$. Omdat $16^{3/2} = 64$ en de wortel positief is, geldt $4p + 4 = 16$. Je vindt $p = 3$.$examentrainingsql$),
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Voor elke $p > 0$ sluit de grafiek van $f(x) = e^{x}$ met de $x$-as, de $y$-as en de lijn $x = p$ een vlakdeel $V_p$ in. Het vlakdeel $W$ wordt ingesloten door de grafiek van $g(x) = 3e^{3x}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan de oppervlakte van $W$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen alle drie de delen: eerst vertaal je het verhaal naar een integraal, daarna reken je die uit (er komt een uitdrukking in $p$ uit), en tot slot los je de vergelijking op. Beide grafieken liggen boven de $x$-as. Je rekent beide oppervlakten uit en stelt ze aan elkaar gelijk.$examentrainingsql$),
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Voor elke $p > 0$ sluit de grafiek van $f(x) = e^{x}$ met de $x$-as, de $y$-as en de lijn $x = p$ een vlakdeel $V_p$ in. Het vlakdeel $W$ wordt ingesloten door de grafiek van $g(x) = 3e^{3x}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan de oppervlakte van $W$.$examentrainingsql$, 1, $examentrainingsql$$O(V_p) = \displaystyle\int_{0}^{p} e^{x}\,\mathrm{d}x$ en $O(W) = \displaystyle\int_{0}^{1} 3e^{3x}\,\mathrm{d}x$. Bij $e^{3x}$ is de kern $3x$, met afgeleide $3$.$examentrainingsql$),
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Voor elke $p > 0$ sluit de grafiek van $f(x) = e^{x}$ met de $x$-as, de $y$-as en de lijn $x = p$ een vlakdeel $V_p$ in. Het vlakdeel $W$ wordt ingesloten door de grafiek van $g(x) = 3e^{3x}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan de oppervlakte van $W$.$examentrainingsql$, 2, $examentrainingsql$Een primitieve van $e^{x}$ is $e^{x}$, dus $O(V_p) = e^{p} - 1$. Een primitieve van $3e^{3x}$ is $e^{3x}$, dus $O(W) = e^{3} - 1$.$examentrainingsql$),
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Voor elke $p > 0$ sluit de grafiek van $f(x) = e^{x}$ met de $x$-as, de $y$-as en de lijn $x = p$ een vlakdeel $V_p$ in. Het vlakdeel $W$ wordt ingesloten door de grafiek van $g(x) = 3e^{3x}$, de $x$-as en de lijnen $x = 0$ en $x = 1$. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan de oppervlakte van $W$.$examentrainingsql$, 3, $examentrainingsql$Deel 3: $e^{p} - 1 = e^{3} - 1$, dus $e^{p} = e^{3}$ en $p = 3$.$examentrainingsql$),
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Voor elke $p > 1$ sluit de grafiek van $f(x) = \ln(x)$ met de $x$-as en de lijnen $x = 1$ en $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $1$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen alle drie de delen: eerst vertaal je het verhaal naar een integraal, daarna reken je die uit (er komt een uitdrukking in $p$ uit), en tot slot los je de vergelijking op. Op $[1, p]$ met $p > 1$ is $\ln(x) > 0$, dus de grafiek ligt boven de $x$-as.$examentrainingsql$),
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Voor elke $p > 1$ sluit de grafiek van $f(x) = \ln(x)$ met de $x$-as en de lijnen $x = 1$ en $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $1$.$examentrainingsql$, 1, $examentrainingsql$$O(V_p) = \displaystyle\int_{1}^{p} \ln(x)\,\mathrm{d}x$.$examentrainingsql$),
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Voor elke $p > 1$ sluit de grafiek van $f(x) = \ln(x)$ met de $x$-as en de lijnen $x = 1$ en $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $1$.$examentrainingsql$, 2, $examentrainingsql$Een primitieve is $F(x) = x\ln(x) - x$. Dus $O(V_p) = (p\ln(p) - p) - (0 - 1) = p\ln(p) - p + 1$.$examentrainingsql$),
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Voor elke $p > 1$ sluit de grafiek van $f(x) = \ln(x)$ met de $x$-as en de lijnen $x = 1$ en $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $1$.$examentrainingsql$, 3, $examentrainingsql$Deel 3: $p\ln(p) - p + 1 = 1$, dus $p(\ln(p) - 1) = 0$. Omdat $p > 1$ is $\ln(p) = 1$, en dus $p = e$.$examentrainingsql$),
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Voor elke $p$ met $0 < p \le \dfrac{\pi}{2}$ sluit de grafiek van $f(x) = \sin(2x)$ met de $x$-as en de lijnen $x = 0$ en $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $1$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen alle drie de delen: eerst vertaal je het verhaal naar een integraal, daarna reken je die uit (er komt een uitdrukking in $p$ uit), en tot slot los je de vergelijking op. Op $\left(0, \dfrac{\pi}{2}\right]$ loopt $2x$ van $0$ tot $\pi$, dus $\sin(2x)$ is daar positief. De oppervlakte is de integraal.$examentrainingsql$),
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Voor elke $p$ met $0 < p \le \dfrac{\pi}{2}$ sluit de grafiek van $f(x) = \sin(2x)$ met de $x$-as en de lijnen $x = 0$ en $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $1$.$examentrainingsql$, 1, $examentrainingsql$$O(V_p) = \displaystyle\int_{0}^{p} \sin(2x)\,\mathrm{d}x$. De kern is $2x$, met afgeleide $2$.$examentrainingsql$),
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Voor elke $p$ met $0 < p \le \dfrac{\pi}{2}$ sluit de grafiek van $f(x) = \sin(2x)$ met de $x$-as en de lijnen $x = 0$ en $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $1$.$examentrainingsql$, 2, $examentrainingsql$Een primitieve is $F(x) = -\dfrac{1}{2}\cos(2x)$. Dus $O(V_p) = -\dfrac{1}{2}\cos(2p) + \dfrac{1}{2} = \dfrac{1 - \cos(2p)}{2}$.$examentrainingsql$),
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Voor elke $p$ met $0 < p \le \dfrac{\pi}{2}$ sluit de grafiek van $f(x) = \sin(2x)$ met de $x$-as en de lijnen $x = 0$ en $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $1$.$examentrainingsql$, 3, $examentrainingsql$Deel 3: $\dfrac{1 - \cos(2p)}{2} = 1$, dus $\cos(2p) = -1$. Op het gegeven stuk is $0 < 2p \le \pi$, en daar geldt dat alleen bij $2p = \pi$. Je vindt $p = \dfrac{\pi}{2}$.$examentrainingsql$),
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Voor elke $p$ met $0 < p \le \dfrac{\pi}{6}$ sluit de grafiek van $f(x) = \cos(3x)$ met de $x$-as en de lijnen $x = 0$ en $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $\dfrac{1}{3}$.$examentrainingsql$, 0, $examentrainingsql$Hier spelen alle drie de delen: eerst vertaal je het verhaal naar een integraal, daarna reken je die uit (er komt een uitdrukking in $p$ uit), en tot slot los je de vergelijking op. Op $\left[0, \dfrac{\pi}{6}\right]$ loopt $3x$ van $0$ tot $\dfrac{\pi}{2}$, dus $\cos(3x)$ is daar positief. De oppervlakte is de integraal.$examentrainingsql$),
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Voor elke $p$ met $0 < p \le \dfrac{\pi}{6}$ sluit de grafiek van $f(x) = \cos(3x)$ met de $x$-as en de lijnen $x = 0$ en $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $\dfrac{1}{3}$.$examentrainingsql$, 1, $examentrainingsql$$O(V_p) = \displaystyle\int_{0}^{p} \cos(3x)\,\mathrm{d}x$. De kern is $3x$, met afgeleide $3$.$examentrainingsql$),
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Voor elke $p$ met $0 < p \le \dfrac{\pi}{6}$ sluit de grafiek van $f(x) = \cos(3x)$ met de $x$-as en de lijnen $x = 0$ en $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $\dfrac{1}{3}$.$examentrainingsql$, 2, $examentrainingsql$Een primitieve is $F(x) = \dfrac{1}{3}\sin(3x)$. Dus $O(V_p) = \dfrac{1}{3}\sin(3p)$.$examentrainingsql$),
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Voor elke $p$ met $0 < p \le \dfrac{\pi}{6}$ sluit de grafiek van $f(x) = \cos(3x)$ met de $x$-as en de lijnen $x = 0$ en $x = p$ een vlakdeel $V_p$ in. Bereken exact de waarde van $p$ waarvoor de oppervlakte van $V_p$ gelijk is aan $\dfrac{1}{3}$.$examentrainingsql$, 3, $examentrainingsql$Deel 3: $\dfrac{1}{3}\sin(3p) = \dfrac{1}{3}$, dus $\sin(3p) = 1$. Op het gegeven stuk is $0 < 3p \le \dfrac{\pi}{2}$, en daar geldt dat alleen bij $3p = \dfrac{\pi}{2}$. Je vindt $p = \dfrac{\pi}{6}$.$examentrainingsql$),
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Het vlakdeel $W$ wordt ingesloten door de grafiek van $f(x) = 4 - x$, de $x$-as en de lijnen $x = 0$ en $x = 4$. Voor elke $p$ met $0 < p < 4$ snijdt de lijn $x = p$ het vlakdeel $W$ in een linkerdeel $V$ en een rechterdeel. Bereken exact de waarde van $p$ waarvoor die twee delen dezelfde oppervlakte hebben.$examentrainingsql$, 0, $examentrainingsql$Hier spelen alle drie de delen: eerst vertaal je het verhaal naar een integraal, daarna reken je die uit (er komt een uitdrukking in $p$ uit), en tot slot los je de vergelijking op. De grafiek van $f(x) = 4 - x$ ligt op $[0, 4]$ boven de $x$-as. Het linkerdeel $V$ loopt van $x = 0$ tot $x = p$.$examentrainingsql$),
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Het vlakdeel $W$ wordt ingesloten door de grafiek van $f(x) = 4 - x$, de $x$-as en de lijnen $x = 0$ en $x = 4$. Voor elke $p$ met $0 < p < 4$ snijdt de lijn $x = p$ het vlakdeel $W$ in een linkerdeel $V$ en een rechterdeel. Bereken exact de waarde van $p$ waarvoor die twee delen dezelfde oppervlakte hebben.$examentrainingsql$, 1, $examentrainingsql$Eerst de hele oppervlakte: $O(W) = \displaystyle\int_{0}^{4} (4 - x)\,\mathrm{d}x$. Het linkerdeel is $O(V) = \displaystyle\int_{0}^{p} (4 - x)\,\mathrm{d}x$.$examentrainingsql$),
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Het vlakdeel $W$ wordt ingesloten door de grafiek van $f(x) = 4 - x$, de $x$-as en de lijnen $x = 0$ en $x = 4$. Voor elke $p$ met $0 < p < 4$ snijdt de lijn $x = p$ het vlakdeel $W$ in een linkerdeel $V$ en een rechterdeel. Bereken exact de waarde van $p$ waarvoor die twee delen dezelfde oppervlakte hebben.$examentrainingsql$, 2, $examentrainingsql$Een primitieve is $F(x) = 4x - \dfrac{1}{2}x^{2}$. Dus $O(W) = 8$, en $O(V) = 4p - \dfrac{1}{2}p^{2}$. Het rechterdeel heeft oppervlakte $8 - O(V)$.$examentrainingsql$),
  ('examen_opp_parameter', 'examen_opp_parameter', $examentrainingsql$Het vlakdeel $W$ wordt ingesloten door de grafiek van $f(x) = 4 - x$, de $x$-as en de lijnen $x = 0$ en $x = 4$. Voor elke $p$ met $0 < p < 4$ snijdt de lijn $x = p$ het vlakdeel $W$ in een linkerdeel $V$ en een rechterdeel. Bereken exact de waarde van $p$ waarvoor die twee delen dezelfde oppervlakte hebben.$examentrainingsql$, 3, $examentrainingsql$Deel 3: de delen zijn even groot, dus $O(V) = 4$. Dan $4p - \dfrac{1}{2}p^{2} = 4$. Vermenigvuldig met $2$: $p^{2} - 8p + 8 = 0$. De oplossingen zijn $p = 4 \pm 2\sqrt{2}$. Alleen $p = 4 - 2\sqrt{2}$ ligt tussen $0$ en $4$.$examentrainingsql$)
) AS v(topic_slug, cluster_slug, latex_body, step_order, step_description)
JOIN public.topics_new t ON t.slug = v.topic_slug AND t.site = 'integralen'
JOIN public.topic_clusters_new cl ON cl.slug = v.cluster_slug AND cl.topic_id = t.id
JOIN public.questions_new vr ON vr.latex_body = v.latex_body AND vr.cluster_id = cl.id
ON CONFLICT (question_id, step_order) DO NOTHING;

-- 6. Controle
DO $do$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM public.questions_new WHERE cluster_id = (SELECT id FROM public.topic_clusters_new WHERE slug = 'examen_opp_parameter' AND topic_id = (SELECT id FROM public.topics_new WHERE slug = 'examen_opp_parameter' AND site = 'integralen'));
  IF n <> 8 THEN RAISE EXCEPTION 'Cluster examen_opp_parameter hoort 8 vragen te hebben, gevonden %', n; END IF;
  SELECT count(*) INTO n FROM public.question_steps_new s
  JOIN public.questions_new vr ON vr.id = s.question_id
  JOIN public.topics_new t ON t.id = vr.topic_id
  WHERE t.site = 'integralen' AND t.slug IN ('examen_opp_parameter');
  IF n <> 32 THEN RAISE EXCEPTION 'Deze topics horen samen 32 stappen te hebben, gevonden %', n; END IF;
END $do$;

COMMIT;
